import React from 'react';
import { Link } from 'react-router-dom';
import SeverityBadge from '../ui/SeverityBadge';

export default function LiveQueueFeed({ reports }) {
  return <section className="panel feed-panel"><div className="panel-heading"><div><h2>Live report feed <span className="live-pill"><i/> LIVE</span></h2><p>Recent reports from citizens</p></div><Link className="text-button" to="/reports">View all →</Link></div><div className="feed-list">{reports.slice(0, 4).map(report => <Link className="feed-item" key={report.id} to={`/reports/${report.id}`}><div className={`feed-icon ${report.severity.toLowerCase()}`}>⌖</div><div className="feed-body"><div className="feed-top"><b>{report.category}</b><time>{report.date.split(',')[0]}</time></div><p>{report.location}</p><div className="feed-bottom"><span>{report.id}</span><SeverityBadge severity={report.severity}/></div></div></Link>)}</div><Link className="feed-footer" to="/reports">Open reports queue <span>→</span></Link></section>;
}
